    yaml: "apiVersion: ladder.dev/v1alpha1\nkind: WorkflowBundle\nmetadata:\n  name: insurance-claim-review\n  title: Insurance claim review bundle\n  description: Claim intake, supporting contract, ontology sliver, independent review, and approval output.\n  version: 1.0.0\nspec:\n  workflowRef: ladder://workflows/builtin/wf-insr-01\n  ontology:\n    ref: ladder://ontologies/builtin/insurance\n    mode: sliver\n    selection:\n      typeIds: []\n      propertyRefs:\n        - insurance_claim.claim_number\n        - insurance_policy.policy_number\n        - loss_event.loss_date\n        - loss_event.loss_description\n        - coverage.coverage_position\n        - claim_adjustment.recommended_reserve\n      relationshipIds:\n        - governs\n        - arises_from\n        - evaluated_as\n        - contains\n  forms:\n    - ref: ladder://forms/builtin/first-notice-of-loss\n      role: start\n    - ref: ladder://forms/builtin/claim-review-decision\n      role: approval\n  documents:\n    - ref: ladder://documents/builtin/insurance-claim-file\n      role: supporting\n  bindings:\n    - id: claim-file-to-intake\n      description: Provide the normalized claim-file contract to the workflow intake.\n      source:\n        ref: ladder://documents/builtin/insurance-claim-file\n        path: /spec\n      target:\n        ref: ladder://workflows/builtin/wf-insr-01\n        path: /spec/nodes/0/inputSchema/properties/workflowFields/properties/claim_documentation\n      direction: input\n    - id: policy-wording-to-intake\n      source:\n        ref: ladder://forms/builtin/first-notice-of-loss\n        path: /spec/pages/0/sections/2/fields/0\n      target:\n        ref: ladder://workflows/builtin/wf-insr-01\n        path: /spec/nodes/0/inputSchema/properties/workflowFields/properties/policy_wording\n      ontologyPropertyRef: insurance_policy.policy_provisions_cited\n      direction: input\n    - id: loss-evidence-to-intake\n      source:\n        ref: ladder://forms/builtin/first-notice-of-loss\n        path: /spec/pages/0/sections/1\n      target:\n        ref: ladder://workflows/builtin/wf-insr-01\n        path: /spec/nodes/0/inputSchema/properties/workflowFields/properties/loss_evidence\n      direction: input\n    - id: history-to-intake\n      source:\n        ref: ladder://forms/builtin/first-notice-of-loss\n        path: /spec/pages/0/sections/2/fields/1\n      target:\n        ref: ladder://workflows/builtin/wf-insr-01\n        path: /spec/nodes/0/inputSchema/properties/workflowFields/properties/prior_claims_history\n      ontologyPropertyRef: loss_event.loss_history_summary\n      direction: input\n    - id: determination-to-decision\n      source:\n        ref: ladder://workflows/builtin/wf-insr-01\n        path: /spec/nodes/1/outputSchema/properties/determination\n      target:\n        ref: ladder://forms/builtin/claim-review-decision\n        path: /spec/pages/0/sections/0/fields/0\n      ontologyPropertyRef: coverage.coverage_position\n      direction: approval\n",
